// Genuary #10: You can only use TAU in your code, no other number allowed


void mainImage( out vec4 C, vec2 R)
{
    float t = 6.283185;
    vec2 U = (R/iResolution.xy)*vec2(t+t, t);
    C = vec4(vec3(dot(sin(U*sqrt(t)-iTime), cos(U.yx*t+iTime)*sqrt(t))), t/*lul*/);
}
